import fs from 'node:fs/promises';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { FIXED_UNITS, formatNumber } from '../dist/assets/core.js';
import { extraPages, extraTool, toolLinks, savedMarkup } from './tools-markup.mjs';

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const data=[...JSON.parse(await fs.readFile(path.join(root,'data/pages.json'),'utf8')),...extraPages];
const keywords=JSON.parse(await fs.readFile(path.join(root,'data/keywords.json'),'utf8'));
const config=JSON.parse(await fs.readFile(path.join(root,'site.config.json'),'utf8'));
const origin=process.env.SITE_URL||config.url||process.env.CF_PAGES_URL||'http://localhost:4173';
const siteURL=new URL(origin).origin;
const publicBuild=siteURL.startsWith('https://')&&!/example\.(com|org)|\.invalid$/.test(new URL(siteURL).hostname);
if(process.env.CF_PAGES&&!publicBuild)throw new Error('Set SITE_URL to the actual HTTPS deployment origin.');
const dist=path.join(root,'dist');
const appSource=await fs.readFile(path.join(dist,'assets/app.js'),'utf8');
const modules=['core','motion','dial','tools-core','tools'];
const sources=new Map([['app',appSource],...await Promise.all(modules.map(async name=>[name,await fs.readFile(path.join(dist,`assets/${name}.js`),'utf8')]))]);
const hash=createHash('sha256');for(const source of sources.values())hash.update(source);
const assetVersion=hash.update(await fs.readFile(path.join(root,'src/styles.css'))).digest('hex').slice(0,12);
for(const [name,source]of sources){let output=source;for(const module of modules)output=output.replaceAll(`from './${module}.js'`,`from './${module}.js?v=${assetVersion}'`);await fs.writeFile(path.join(dist,`assets/${name}.js`),output);}
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json=value=>JSON.stringify(value).replaceAll('<','\\u003c');
const icon=(name,cls='')=>{
  const shapes={clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',convert:'<path d="M4 7h15l-4-4M20 17H5l4 4M19 7l-4 4M5 17l4-4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-12 4h2m3 0h2"/>',date:'<path d="M3 12a9 9 0 1 0 3-6M3 3v6h6M12 7v5l3 2"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V4H4v12h4"/>',expand:'<path d="M9 3H3v6m12-6h6v6M3 15v6h6m6 0h6v-6"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>'};
  return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[name]??shapes.clock}</svg>`;
};
const link=(url,text,cls='')=>`<a class="${cls}" href="${url}">${esc(text)}${cls.includes('arrow')?icon('arrow'):''}</a>`;
const label=(id,text,control,hint='')=>`<div class="field"><label for="${id}">${text}</label>${control}${hint?`<small>${hint}</small>`:''}</div>`;
const select=(id,options,value='')=>`<select id="${id}">${options.map(([v,t])=>`<option value="${v}"${String(v)===String(value)?' selected':''}>${t}</option>`).join('')}</select>`;
const dateInput=(id)=>`<input type="date" id="${id}" min="0100-01-01" max="9999-12-31" data-today required>`;
const status='<p id="tool-status" role="status" aria-live="polite" class="tool-status"></p>';
const resultSummary='<p id="result-summary" class="sr-only"></p>';
const copyButton=`<button type="button" id="copy-result" class="quiet-button">${icon('copy')} Copy result</button>`;
const unitTable=(id,rows)=>{
  const table=`<div class="table-scroll"><table><thead><tr><th scope="col">Unit / reference</th><th scope="col">Result</th></tr></thead><tbody id="${id}">${rows.map(row=>`<tr><th scope="row">${esc(row[0])}</th><td>${esc(row[1])}</td></tr>`).join('')}</tbody></table></div>`;
  return id==='conversion-units'?`<details class="result-breakdown"><summary>View all unit conversions</summary>${table}</details>`:table;
};

function typeOf(p){
  if(p.tool)return {type:p.tool};
  if(p.route==='/')return {type:'home',hour:15,minute:0};
  if(p.route==='/how-long-until/')return {type:'clock',hour:15,minute:0};
  if(p.route==='/time-duration-converter/')return {type:'converter',amount:72,unit:'hours'};
  if(p.route==='/years-ago-calculator/')return {type:'years',year:2018};
  if(p.route.includes('business-days')){
    const match=/\/(3|5|3-5)-business-days\//.exec(p.route);
    return {type:'business',businessMin:match?Number(match[1].split('-')[0]):3,businessMax:match?.[1]==='3-5'?5:undefined};
  }
  if(p.route.startsWith('/how-long-ago-was/'))return {type:'years',year:Number(p.route.split('/')[2])};
  if(p.route.includes('a-fortnight')||p.route.includes('a-century'))return {type:'definition',definition:p.route.includes('a-fortnight')?'fortnight':'century'};
  const duration=/\/how-long-is\/(\d+)-(seconds|minutes|hours|days|weeks|months)\//.exec(p.route);
  if(duration)return {type:'duration',amount:Number(duration[1]),unit:duration[2]};
  if(p.route.startsWith('/how-long-until/')){
    const target=p.route.split('/')[2];
    if(['halloween','thanksgiving'].includes(target))return {type:'holiday',holiday:target};
    const match=/^(\d{1,2})(?:-(\d{2}))?(?:-(am|pm))?$/.exec(target);
    if(match){const hour=Number(match[1]),minute=Number(match[2]??0),meridiem=match[3];return {type:meridiem?'clock':'ambiguous',hour:meridiem?(hour%12+(meridiem==='pm'?12:0)):hour,minute};}
  }
  return {type:p.route==='/holiday-countdown/'?'holiday-hub':'legal'};
}

function breadcrumbItems(item,p){
  if(item.route==='/')return [];
  const parent={clock:'/how-long-until/',ambiguous:'/how-long-until/',holiday:'/holiday-countdown/',duration:'/time-duration-converter/',converter:'/time-duration-converter/',definition:'/time-duration-converter/',business:'/business-days-calculator/',years:'/years-ago-calculator/'}[p.type];
  const items=[{name:'Home',route:'/'}];
  if(parent&&parent!==item.route){const hub=data.find(x=>x.route===parent);items.push({name:hub.h1.replace(/\?$/,''),route:parent});}
  items.push({name:item.h1.replace(/\?$/,''),route:item.route});
  return items;
}

function calculationSources(p){
  const refs=[];
  if(['clock','ambiguous','holiday','interval','event','zones'].includes(p.type))refs.push('<a href="https://www.iana.org/time-zones">IANA time-zone database</a> (time-zone rules are supplied by your browser)');
  if(p.type==='holiday'&&p.holiday==='thanksgiving')refs.push('<a href="https://www.opm.gov/policy-data-oversight/pay-leave/federal-holidays/">US Office of Personnel Management</a> (US Thanksgiving dates)');
  if(p.type==='years'||p.type==='definition'||p.type==='dates'||p.unit==='months')refs.push('<a href="https://aa.usno.navy.mil/faq/calendars">US Naval Observatory calendar guide</a> (Gregorian leap-year rules)');
  if(['duration','converter','arithmetic'].includes(p.type)&&p.unit!=='months')refs.push('<a href="https://www.bipm.org/en/publications/si-brochure">BIPM SI Brochure</a> (time-unit reference)');
  if(!refs.length)return '';
  return `<aside class="source-note" aria-label="Calculation references"><h2>Calculation references</h2><p>${refs.join('; ')}. Month-end clamping and countdown target conventions are ${esc(config.name)}’s stated calculation choices. References checked October 26, 2026.</p></aside>`;
}

function header(active){return `<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="header-inner"><a href="/" class="brand" aria-label="${esc(config.name)} home"><span class="brand-symbol">${icon('clock')}</span><span class="brand-name">${esc(config.name).replace(" Calculator","<span>Calculator</span>")}</span></a><nav id="main-nav" aria-label="Main navigation">${[['/time-duration-calculator/','Duration calculator','interval'],['/how-long-until/','Countdowns','clock'],['/time-duration-converter/','Time converter','duration'],['/business-days-calculator/','Business days','business'],['/date-calculator/','Date calculator','dates']].map(([url,text,type])=>`<a href="${url}"${active===type?' aria-current="page"':''}>${text}</a>`).join('')}</nav><div class="header-actions"><button id="open-search" type="button" class="icon-button" aria-label="Search all tools">${icon('search')}</button><button id="theme-toggle" type="button" class="icon-button" aria-label="Toggle dark theme" aria-pressed="false">${icon('sun')}</button><button id="menu-toggle" type="button" class="icon-button menu-toggle" aria-label="Toggle navigation" aria-expanded="false" aria-controls="main-nav">${icon('menu')}</button></div></div></header>`;}
function footer(){return `<footer class="site-footer"><div><a href="/" class="brand footer-brand"><span class="brand-name">${esc(config.name).replace(" Calculator","<span>Calculator</span>")}</span></a><p>Simple tools for the time in your day.</p><small>Calculations stay on your device. No account required.</small></div><nav aria-label="Footer">${[['/about/','About'],['/contact/','Contact'],['/privacy/','Privacy'],['/terms/','Terms']].map(([url,text])=>link(url,text)).join('')}</nav></footer>`;}

function clockTool(p,small=false){
  const holiday=p.type==='holiday',ambiguous=p.type==='ambiguous';
  const time=`${String(p.hour??0).padStart(2,'0')}:${String(p.minute??0).padStart(2,'0')}`;
  return `<section class="tool-layout ${small?'home-tool':''}" aria-label="Live countdown calculator"><div class="result-panel countdown-panel" id="result-panel"><div class="result-eyebrow"><span class="live-dot"></span> LIVE COUNTDOWN <span class="device-badge">Your time zone</span></div><div class="countdown-title">Time until <strong id="target-label">${holiday?esc(p.holiday):p.hour!==undefined?`${(p.hour%12)||12}:${String(p.minute??0).padStart(2,'0')} ${p.hour>=12?'PM':'AM'}`:'3:00 PM'}</strong></div><div class="digits" aria-label="Time remaining">${holiday?'<div><strong id="count-days">—</strong><span>days</span></div>':'<span id="count-days" hidden></span>'}<div><strong id="count-hours">—</strong><span>hours</span></div><span class="colon">:</span><div><strong id="count-minutes">—</strong><span>minutes</span></div><span class="colon">:</span><div><strong id="count-seconds">—</strong><span>seconds</span></div></div><p id="countdown-note" class="countdown-note">Uses your device clock and selected time zone.</p><div class="clock-metadata"><div><span>CURRENT LOCAL TIME</span><strong id="clock-now">Reading your clock…</strong></div><div><span>TARGET DATE & TIME</span><strong id="target-date">Calculated on your device</strong></div></div>${ambiguous?`<div class="dual-results"><div><span>${(p.hour%12)||12}:${String(p.minute).padStart(2,'0')} AM</span><strong id="am-result">Calculating…</strong></div><div><span>${(p.hour%12)||12}:${String(p.minute).padStart(2,'0')} PM</span><strong id="pm-result">Calculating…</strong></div></div>`:''}<div class="result-actions">${copyButton}<button type="button" class="quiet-button" id="fullscreen">${icon('expand')} Full screen</button><button type="button" class="quiet-button" id="share-countdown">Share settings ${icon('arrow')}</button></div>${resultSummary}</div><div class="control-panel"><h2>Set your countdown</h2>${holiday?'<div hidden>':''}${label('target-time','Target time',`<input id="target-time" type="time" value="${time}" required>${!holiday?'<button type="button" class="text-button" id="switch-am-pm">Switch AM / PM</button>':''}`)}${label('target-day','Count down to',select('target-day',[['next','Next occurrence'],['today','Today only'],['tomorrow','Tomorrow']],'next'))}${holiday?'</div><p class="field-help">This holiday countdown targets midnight on its defined date.</p>':''}${label('time-zone','Time zone','<select id="time-zone" data-time-zone></select>')}${label('clock-format','Clock format',select('clock-format',[['12','12-hour (AM / PM)'],['24','24-hour']],'12'))}<p><a href="/countdown-to-date/">Choose a specific date or event</a></p><div class="quick-times" aria-label="Quick target times"${holiday?' hidden':''}>${[['12:00','Noon'],['15:00','3 PM'],['17:00','5 PM'],['00:00','Midnight']].map(([t,text])=>`<button type="button" data-time="${t}">${text}</button>`).join('')}</div><details class="alert-options"><summary>Optional alerts</summary><label class="checkbox-label"><input type="checkbox" id="sound-alert"> Sound when the target is reached</label><button type="button" id="sound-test" class="quiet-button">Test sound</button><button type="button" id="sound-stop" class="quiet-button">Stop sound</button><button type="button" id="enable-notifications" class="text-button">Enable browser notification</button><small>Keep this page open and your device awake. Sound and notifications depend on browser permission.</small></details>${status}</div></section><noscript><p class="notice">Live countdowns need JavaScript. This page’s time rules, examples and links remain available below.</p></noscript><section class="inline-units"><h2>Time remaining in other units</h2>${unitTable('countdown-units',[['Hours','Live value calculated in your browser'],['Minutes','Updates with the countdown'],['Seconds','Updates with the countdown']])}</section>`;
}

function durationAnswer(p){
  if(p.unit==='months'){const y=Math.floor(p.amount/12),m=p.amount%12;return `${p.amount} months = ${y} year${y!==1?'s':''}${m?` and ${m} month${m!==1?'s':''}`:''}.`;}
  const seconds=p.amount*FIXED_UNITS[p.unit];
  const target=p.unit==='seconds'?'minutes':p.unit==='minutes'?'hours':p.unit==='hours'?'days':p.unit==='days'?'weeks':'days';
  return `${formatNumber(p.amount)} ${p.unit} = ${formatNumber(seconds/FIXED_UNITS[target])} ${target}.`;
}

function durationTool(p){
  const month=p.unit==='months';
  const units=[...Object.keys(FIXED_UNITS),'months','years'];
  return `<p id="conversion-lead" class="answer-lead">${p.type==='converter'?'':'Preset answer: '}${durationAnswer(p)}${p.unit==='minutes'?` That is ${Math.floor(p.amount/60)} ${Math.floor(p.amount/60)===1?'hour':'hours'} and ${p.amount%60} ${p.amount%60===1?'minute':'minutes'}.`:''}</p><section class="tool-layout" aria-label="Time duration converter"><div class="result-panel" id="result-panel"><div class="result-eyebrow">${icon('convert')} YOUR CONVERSION</div><p class="result-caption" id="conversion-caption">${p.amount} ${p.unit}</p><div class="primary-value" id="conversion-result">${durationAnswer(p).split(' = ')[1]}</div>${unitTable('conversion-units',month?[['Calendar months',String(p.amount)],['Days','Depends on your start date']]:Object.entries(FIXED_UNITS).map(([unit,factor])=>[unit,formatNumber(p.amount*FIXED_UNITS[p.unit]/factor)]))}<div class="result-actions">${copyButton}</div>${resultSummary}</div><div class="control-panel"><h2>Adjust the duration</h2>${label('duration-value','Amount',`<input id="duration-value" type="number" value="${p.amount}" step="any" min="-1000000000000" max="1000000000000" required>`)}${label('duration-unit','Unit',select('duration-unit',units.map(u=>[u,u[0].toUpperCase()+u.slice(1)]),p.unit))}${label('conversion-target','Convert to',select('conversion-target',Object.keys(FIXED_UNITS).map(u=>[u,u[0].toUpperCase()+u.slice(1)]),p.unit==='seconds'?'minutes':p.unit==='minutes'?'hours':p.unit==='hours'?'days':p.unit==='days'?'weeks':'days'))}${label('duration-composite','Compound duration (optional)',`<input id="duration-composite" maxlength="100" placeholder="e.g. 1:30:00 or 1h 30m">`,'When entered, this replaces Amount and Unit in fixed-unit mode.')}${label('duration-mode','Calculation method',select('duration-mode',[['fixed','Exact fixed units'],['calendar','Calendar date calculation'],['approximate','Approximate months & years']],month?'calendar':'fixed'))}<div id="calendar-fields"${month?'':' hidden'}>${label('calendar-start','Start date',dateInput('calendar-start'),'Calendar months keep the same day when possible; otherwise, the last day of the target month.')}</div><p class="field-help">Exact units use 24-hour days. Calendar dates can span 23- or 25-hour days when clocks change.</p>${status}</div></section><section class="from-now"><div><h2>When does this duration end?</h2><p>Add the current fixed duration to the time on your device.</p></div><button class="button secondary" type="button" id="add-from-now">Calculate from now ${icon('arrow')}</button><p id="from-now-result" role="status"></p><a id="from-now-countdown" class="button secondary" href="/countdown-to-date/" hidden>Start this countdown</a></section>`;
}

function businessTool(p){return `<p class="answer-lead">${p.businessMax?'3–5 business days is a range of working dates, excluding weekends.':'businessMin' in p?`${p.businessMin} business days means ${p.businessMin} working days, with the end date depending on when you start.`:'Add or subtract working days from any date.'}</p><section class="tool-layout"><div class="result-panel" id="result-panel"><div class="result-eyebrow">${icon('calendar')} YOUR DATE RESULT</div><p class="result-caption" id="business-caption">Calculated from your start date</p><div class="primary-value date-value" id="business-result">Choose your start date</div><p class="field-help">Only the selected weekend days and dates you explicitly exclude are skipped.</p><div class="result-actions">${copyButton}</div>${resultSummary}</div><div class="control-panel"><h2>Working-day rules</h2>${label('business-mode','Task',select('business-mode',[['advance','Add or subtract business days'],['between','Count business days between dates']]))}${label('business-start','Start date',dateInput('business-start'))}<div class="field-pair" id="business-advance-fields">${label('business-count','Business days',`<input type="number" id="business-count" min="-10000" max="10000" step="1" value="${p.businessMin??3}" required>`)}${label('business-range-end','Range end (optional)',`<input type="number" id="business-range-end" min="-10000" max="10000" step="1" value="${p.businessMax??''}" placeholder="e.g. 5">`)}</div><div id="business-between-fields" hidden>${label('business-end','End date',dateInput('business-end'))}<label class="checkbox-label"><input type="checkbox" id="business-include-end" checked> Include the end date if it is a working day</label></div>${label('weekend-rule','Weekend days',select('weekend-rule',[['sat-sun','Saturday & Sunday'],['fri-sat','Friday & Saturday'],['sun','Sunday only'],['none','No weekend exclusion']],'sat-sun'))}<label class="checkbox-label"><input type="checkbox" id="include-start"> Include the start date if it is a working day</label><label class="checkbox-label"><input type="checkbox" id="business-federal"> Exclude observed US federal holidays (2021–2100, Monday–Friday)</label><p class="field-help">Optional standard federal calendar; company, state and local closures may differ. <a href="https://www.opm.gov/policy-data-oversight/pay-leave/federal-holidays/">OPM reference</a>.</p><p id="business-breakdown" hidden></p><details class="exclude-options"><summary>Exclude holidays or other dates</summary>${label('excluded-dates','Excluded dates','<textarea id="excluded-dates" rows="3" placeholder="2026-12-25&#10;2027-01-01"></textarea>','Enter YYYY-MM-DD, one per line. No holiday calendar is applied unless selected above.')}</details>${status}</div></section><section class="explanation"><h2>How the dates are counted</h2><p id="business-step-note">Every included and skipped date is shown below.</p><div class="table-scroll"><table><thead><tr><th scope="col">Date</th><th scope="col">Rule</th><th scope="col">Day number</th></tr></thead><tbody id="business-steps"></tbody></table></div></section>`;}

function yearsTool(p){return `<p class="answer-lead">A year covers a range of dates. Compare its first and last day, or choose an exact date for a precise result.</p><section class="tool-layout"><div class="result-panel" id="result-panel"><div class="result-eyebrow">${icon('date')} TIME BETWEEN DATES</div><div class="primary-value date-value" id="years-result">${p.year}</div>${unitTable('years-details',[['Year begins',`${p.year}-01-01`],['Year ends',`${p.year}-12-31`],['Reference date','Your local date, calculated in your browser']])}<div class="result-actions">${copyButton}</div>${resultSummary}</div><div class="control-panel"><h2>Choose your reference points</h2>${label('year-value','Year',`<input type="number" id="year-value" min="100" max="9999" step="1" value="${p.year}" required>`)}${label('month-value','Month (optional)',select('month-value',[['0','Whole year'],...Array.from({length:12},(_,i)=>[String(i+1),new Intl.DateTimeFormat('en-US',{month:'long',timeZone:'UTC'}).format(new Date(Date.UTC(2020,i,1)))])],'0'))}${label('exact-date','Exact date (optional)','<input type="date" id="exact-date" min="0100-01-01" max="9999-12-31">','If selected, this exact date replaces the year/month range above.')}${label('reference-date','Compare with',dateInput('reference-date'))}<p class="field-help">Results use calendar years, months and days. Total days count calendar boundaries, rather than 24-hour periods.</p>${status}</div></section>`;}

function definitionTool(p){const fortnight=p.definition==='fortnight';return `<p class="answer-lead">${fortnight?'A fortnight is exactly 14 days, or 2 weeks.':'A century is 100 years.'}</p><section class="tool-layout"><div class="result-panel" id="result-panel"><div class="result-eyebrow">${icon('calendar')} CALENDAR DATE RESULT</div><div class="primary-value date-value" id="definition-result">Choose a start date</div><p class="result-caption" id="definition-caption">Add ${fortnight?'14 calendar days':'100 calendar years'} to your date.</p><div class="result-actions">${copyButton}</div>${resultSummary}</div><div class="control-panel"><h2>Find the date</h2>${label('definition-start','Start date',dateInput('definition-start'))}${label('definition-amount',`Number of ${fortnight?'fortnights':'centuries'}`,`<input type="number" id="definition-amount" value="1" min="-10000" max="10000" step="1" required>`)}<p class="field-help">${fortnight?'This advances the calendar by 14 days per fortnight. Across a daylight-saving change, elapsed hours may differ from 336.':'This advances the calendar by 100 years per century. February 29 is clamped to February 28 if the end year is not a leap year.'}</p>${status}</div></section>`;}

function groups(){return [
  {name:'Count down to a time',description:'A live answer to “how long until?”',icon:'clock',type:'clock',routes:data.filter(p=>['clock','ambiguous'].includes(typeOf(p).type)&&p.route!=='/how-long-until/'),url:'/how-long-until/'},
  {name:'Convert a duration',description:'Seconds, minutes, hours and beyond.',icon:'convert',type:'duration',routes:data.filter(p=>typeOf(p).type==='duration'),url:'/time-duration-converter/'},
  {name:'Calculate working days',description:'An end date, with every skipped day explained.',icon:'calendar',type:'business',routes:data.filter(p=>typeOf(p).type==='business'),url:'/business-days-calculator/'},
  {name:'Look back in time',description:'Years, months and days between dates.',icon:'date',type:'years',routes:data.filter(p=>typeOf(p).type==='years'),url:'/years-ago-calculator/'},
];}
function displayLabel(p){return p.h1.replace(/\? AM and PM Countdowns/,'? (AM & PM)').replace('How Long Until ','').replace('How Long Is ','').replace('How Long Ago Was ','').replace('?','');}
function directory(group,limit,heading='h2'){return `<section class="directory-section"><div class="section-heading"><div class="section-icon">${icon(group.icon)}</div><div><${heading}>${group.name}</${heading}><p>${group.description}</p></div>${link(group.url,'Open tool','arrow-link')}</div><div class="link-grid">${(limit?group.routes.slice(0,limit):group.routes).map(p=>link(p.route,displayLabel(p),'directory-link')).join('')}</div></section>`;}

function explanation(p,route){
  if(p.type==='converter')return `<section class="reading-grid"><article><h2>Choose the right duration conversion</h2><p>Enter an amount and its unit, then select the unit you want to convert to. The initial 72-hour value is an editable example: 72 hours = 3 fixed 24-hour days.</p><h3>Seconds, minutes, hours, days and weeks</h3><p>Exact fixed-unit mode uses 60 seconds per minute, 60 minutes per hour, 24 hours per day and 7 days per week. For example, 90 seconds = 1.5 minutes; 90 minutes = 1.5 hours = 1 hour 30 minutes; and 2 weeks = 14 days.</p><h3>Decimal hours and compound durations</h3><p>For hours and minutes together, enter a compound duration such as 1h 30m or 1:30:00. Decimal 1.5 hours means 1 hour 30 minutes, not 1 hour 5 minutes. A compound entry replaces the separate amount and unit in fixed-unit mode.</p><h3>Months and years need a counting method</h3><p>Choose calendar mode and a start date to add calendar months or years. January 31 plus one month clamps to February 28, or February 29 in a leap year. For an estimated conversion to fixed units, choose approximate mode instead; the result is explicitly labeled as an estimate.</p></article><aside class="method-note"><span class="eyebrow">UNIT GUIDE</span><h3>Elapsed time or calendar dates?</h3><p>A fixed day means 24 hours. A local calendar day can span 23 or 25 elapsed hours when daylight saving changes. Use the ${link('/time-duration-calculator/','time duration calculator')} for elapsed time between dated moments, or the ${link('/date-calculator/','date calculator')} to add calendar dates.</p><p>Approximate mode uses an average year of 365.2425 days and an average month of one twelfth of that. Those averages do not give an exact end date.</p></aside></section><section class="faq"><h2>Duration conversion questions</h2><details><summary>Can I convert a negative or fractional amount?</summary><p>Yes. Fractional amounts are supported. A negative duration represents an amount of time in the opposite direction; it is not automatically a future date.</p></details><details><summary>Can I find when a duration ends?</summary><p>For a fixed duration, choose “Calculate from now” to add it to your device timestamp. For months or years, choose calendar mode and set a start date instead.</p></details></section>`;
  if(route==='/years-ago-calculator/')return `<section class="reading-grid"><article><h2>How to calculate years ago</h2><p>Choose a year and the reference date you want to compare it with. The reference date initially uses today on your device; you can change it to reproduce a past calculation or compare against a future date.</p><h3>A whole year is a date range</h3><p>When you select a year, the calculator compares both January 1 and December 31 with your reference date. This avoids treating an entire year as one exact day. Choose a month to narrow that range to the first and last day of the month.</p><h3>Use an exact date for one precise result</h3><p>Enter a specific day in the exact-date field when you know it. The result gives calendar years, months and days, plus total calendar days. A date after the reference point is labeled “after” rather than presented as time ago.</p><h3>A reproducible example</h3><p>From January 15, 2020 to January 15, 2025 is 5 calendar years, or 1,827 calendar days. The total includes the leap days in 2020 and 2024. Changing either date changes the result.</p></article><aside class="method-note"><span class="eyebrow">DATE METHOD</span><h3>Calendar-aware differences.</h3><p>Complete months are counted from the earlier date, clamping to month end where necessary. Twelve complete months form a calendar year; remaining calendar days are counted separately.</p><p>Calendar days count date boundaries, not fixed 24-hour intervals. For dates and clock times in a specific time zone, use the ${link('/time-duration-calculator/','time duration calculator')}. For a year-specific example, see ${link('/how-long-ago-was/2018/','how long ago was 2018')}.</p></aside></section>`;
  if(['clock','ambiguous','holiday'].includes(p.type)){
    const target=p.type==='holiday'?p.holiday==='halloween'?'Halloween':'US Thanksgiving':p.type==='ambiguous'?`${p.hour}:${String(p.minute).padStart(2,'0')} AM or PM`:`${p.hour%12||12}:${String(p.minute).padStart(2,'0')} ${p.hour>=12?'PM':'AM'}`;
    const holiday=p.type==='holiday';
    return `<section class="reading-grid"><article><h2>How this countdown works</h2><p>${holiday?(p.holiday==='halloween'?'Halloween is October 31. This countdown targets the beginning of that date at midnight.':'In the United States, Thanksgiving is the fourth Thursday of November. This countdown targets midnight at the beginning of that date.'):`The tool finds the next ${target} in your selected time zone and subtracts the current timestamp. The result updates every second, without reloading the page.`}</p><p>${p.type==='ambiguous'?'Because the query does not specify AM or PM, both are shown above. Choose your intended time before sharing or enabling an alert.':!holiday?`The 24-hour clock equivalent is ${String(p.hour).padStart(2,'0')}:${String(p.minute).padStart(2,'0')}. AM is before noon, while PM is from noon to midnight.`:'The target year and time zone are shown with the result. After the target passes, the next year is selected.'}</p><h3>What if today’s time has passed?</h3><p>“Next occurrence” rolls to the next eligible date. “Today only” states that the time has passed, rather than displaying a negative countdown or pretending tomorrow is today.</p></article><aside class="method-note"><span class="eyebrow">ACCURACY NOTE</span><h3>Your clock. Your time zone.</h3><p>Daylight-saving changes can make a local day 23 or 25 hours long. We calculate between actual instants instead of assuming every day is 24 hours.</p><p>If a target time is skipped when clocks move forward, it moves forward by that gap. During a repeated hour, the next still-future occurrence is used.</p></aside></section><section class="faq"><h2>Good to know</h2><details><summary>Does this use my local time?</summary><p>Yes. It starts with your device’s time zone. You can choose another zone above. The result is only as accurate as your device clock.</p></details><details><summary>Can I leave the countdown running in another tab?</summary><p>Yes. The displayed value is recalculated from the current clock, so browser timer throttling does not accumulate a timing error. Keep your device awake for alerts.</p></details><details><summary>What does a shared countdown link mean?</summary><p>“Share settings” includes the selected clock time, day rule and time zone in the URL fragment. The recipient counts to the next occurrence in that specified zone, not a silently changed local time.</p></details></section>`;
  }
  if(p.type==='duration'||p.type==='converter'){
    const months=p.unit==='months';
    const example=months?`${p.amount} calendar months makes ${Math.floor(p.amount/12)} whole years and ${p.amount%12} remaining months. The number of days depends on the start date and leap years; use calendar mode for an exact end date.`:p.unit==='minutes'?`${p.amount} minutes is ${Math.floor(p.amount/60)} whole ${Math.floor(p.amount/60)===1?'hour':'hours'} and ${p.amount%60} remaining ${p.amount%60===1?'minute':'minutes'}. Divide by 60 for decimal hours: ${formatNumber(p.amount/60)} hours. A decimal part of an hour is not a number of minutes.`:p.unit==='seconds'?`${p.amount} seconds is ${Math.floor(p.amount/60)} whole ${Math.floor(p.amount/60)===1?'minute':'minutes'} and ${p.amount%60} remaining ${p.amount%60===1?'second':'seconds'}. Divide by 60 for decimal minutes: ${formatNumber(p.amount/60)} minutes.`:`${durationAnswer(p)} In fixed units, this is ${formatNumber(p.amount*FIXED_UNITS[p.unit])} seconds. Adding this elapsed duration to a timestamp can give a different local clock time from adding calendar dates across a daylight-saving change.`;
    const formula=months?`${p.amount} ÷ 12 = ${Math.floor(p.amount/12)} whole years, with ${p.amount%12} months remaining.`:`${p.amount} ${p.unit} × ${formatNumber(FIXED_UNITS[p.unit])} seconds per ${p.unit.slice(0,-1)} = ${formatNumber(p.amount*FIXED_UNITS[p.unit])} seconds.`;
    return `<section class="reading-grid"><article><h2>${p.type==='converter'?'Worked example: how to convert':'How to convert'} ${p.amount} ${p.unit}</h2><p>${durationAnswer(p)}</p><div class="formula">${formula}</div><p>${months?'A calendar month can have 28, 29, 30 or 31 days. Select a start date above to find an exact end date. For example, January 31 plus one month ends on February 28, or February 29 in a leap year.':'Fixed conversions use 60 seconds in a minute, 60 minutes in an hour, 24 hours in a day and 7 days in a week. Fractional values are supported; a negative duration represents time in the opposite direction.'}</p><h3>Duration and calendar date are different tasks</h3><p>${example}</p></article><aside class="method-note"><span class="eyebrow">UNIT GUIDE</span><h3>Exact or approximate?</h3><p>Months and years are not fixed numbers of seconds. Calendar mode uses your start date. Approximate mode clearly labels an average year of 365.2425 days and an average month of one twelfth of that.</p><p>For example, 52 weeks is exactly 364 fixed days. A calendar year is normally 365 or 366 days.</p></aside></section><section class="faq"><h2>Common questions</h2><details><summary>How long is ${p.amount} ${p.unit} in other units?</summary><p>${durationAnswer(p)} The conversion table gives other units. For months, enter a calendar start date to obtain the actual number of days.</p></details><details><summary>Can I calculate ${p.amount} ${p.unit} from now?</summary><p>For fixed units, use “Calculate from now” above. For calendar months or years, choose calendar mode and enter the start date. These modes use different, explicitly stated rules.</p></details></section>`;
  }
  if(p.type==='business')return `<section class="reading-grid"><article><h2>Business days depend on your start date</h2><p>A business day is a day that matches the working schedule you select. The default schedule skips Saturday and Sunday. It does not automatically skip public holidays, school closures or company-specific days off.</p><h3>A concrete example</h3><p>Starting on Friday, October 23, 2026, excluding the start date and skipping Saturday/Sunday: Monday the 26th is day 1, Tuesday the 27th is day 2, and Wednesday the 28th is day 3. Five business days ends on Friday the 30th. Therefore 3–5 business days spans October 28–30 in this example.</p><p>Change the starting date above for your own result. The calendar table shows exactly which dates are counted or skipped.</p></article><aside class="method-note"><span class="eyebrow">COUNTING RULE</span><h3>Make the assumptions visible.</h3><p>Use a negative number to count backward. Zero returns the start date. Including the start date counts it only if it is an eligible working day.</p><p>A 1–3 or 2–3 business-day range can be entered in the two number fields. Both endpoints are calculated independently under the same rules.</p></aside></section>`;
  if(p.type==='years')return `<section class="reading-grid"><article><h2>How long ago was ${p.year}?</h2><p>${p.year} ran from January 1 through December 31. The elapsed time depends on which date you mean and the date you compare it with. The tool above shows both endpoints rather than treating a whole year as one date.</p><h3>How long ago was August ${p.year}?</h3><p>Select August in the month field to compare August 1 and August 31 with your reference date. Enter a specific day in the exact-date field for a single precise result.</p><p>The result is expressed in calendar years, months and days, along with total calendar days. The reference date defaults to the current date on your device and can be changed.</p></article><aside class="method-note"><span class="eyebrow">DATE METHOD</span><h3>Calendar-aware differences.</h3><p>We add complete calendar months from the earlier date, clamping at month end when necessary, then count remaining days. Twelve complete months form a calendar year.</p><p>Future dates are explicitly labeled “after” the reference date. Days count calendar boundaries; they do not assume 24 elapsed hours per local day.</p></aside></section>`;
  if(p.type==='definition')return `<section class="reading-grid"><article><h2>${p.definition==='fortnight'?'A fortnight means two weeks':'A century means one hundred years'}</h2><p>${p.definition==='fortnight'?'The word fortnight names a period of fourteen days. That is exactly two seven-day weeks. In fixed 24-hour units, 14 days equals 336 hours or 20,160 minutes. The calendar tool above advances the date by fourteen days.':'The first century covered years 1–100, so the 21st century covers 2001–2100. There was no year zero in this numbering convention. A century is always 100 years, but the number of days depends on which leap years it includes.'}</p><h3>A calendar example</h3><p>${p.definition==='fortnight'?'A fortnight after Friday, October 23, 2026 is Friday, November 6, 2026. It is a calendar-date calculation, so a clock change during those weeks can change the elapsed hours.':'January 1, 2000 to January 1, 2100 spans 36,525 calendar days, while January 1, 1900 to January 1, 2000 spans 36,524. Gregorian years divisible by 100 are leap years only when they are also divisible by 400.'}</p></article><aside class="method-note"><span class="eyebrow">TRY A DATE</span><h3>Go forward or backward.</h3><p>Use the calculator to find the date after one or more ${p.definition==='fortnight'?'fortnights':'centuries'}. A negative number moves backward. If the target month has no matching day, the date is clamped to its last day.</p></aside></section>`;
  return '';
}

function legalContent(route){
  if(route==='/about/')return `<div class="prose"><p class="lede">${esc(config.name)} is a collection of practical time and date tools. Each page starts with the task you came to solve.</p><h2>How calculations work</h2><p>Calculations run in your browser. Fixed durations are kept separate from calendar dates. Working-day calculations show the dates they skip, and countdowns display the selected time zone and target date.</p><h2>Accuracy and limitations</h2><p>Time-zone rules come from your browser’s IANA time-zone data. Your device clock must be correct. Business-day tools do not silently apply holiday calendars. Calendar month operations clamp to month end if the same day does not exist.</p><h2>Review the implementation</h2><p>The calculation code, automated tests and keyword-to-page coverage are maintained in the ${link(config.repository,'project repository')}. To report a problem, use the ${link('/contact/','contact page')}.</p><h2>No account needed</h2><p>You can use the tools without registration. Inputs are processed on your device. See our ${link('/privacy/','privacy policy')} for details.</p></div>`;
  if(route==='/contact/')return `<div class="prose"><p class="lede">Found a date that looks wrong, or have a suggestion? A reproducible example helps us investigate.</p><h2>Report an issue</h2><p>${link(config.repository+'/issues/new','Open an issue on GitHub','button')} ${config.contactEmail?link('mailto:'+config.contactEmail,config.contactEmail,'button secondary contact-email'):''}</p><p>GitHub requires an account to submit an issue. Do not include private dates, personal information or confidential details in a public report.</p><h2>What to include</h2><ul><li>The page you used and the values you entered.</li><li>Your selected time zone and counting rules.</li><li>The result you expected and the result you saw.</li></ul><button id="copy-report" type="button" class="button secondary">${icon('copy')} Copy a report template</button>${status}<p>This opens a template on your device. No report is sent automatically.</p></div>`;
  if(route==='/privacy/')return `<div class="prose"><p class="lede">Your calculator inputs are processed on your device.</p><h2>Information entered into tools</h2><p>Dates, durations, excluded working dates and time-zone selections are calculated in your browser. This application does not send them to a database or third-party calculation API. Optional shared countdown links include the settings you choose in the URL fragment; share them only with people you intend.</p><h2>Local preferences</h2><p>We use browser local storage to remember your light/dark theme and 12/24-hour clock preference. You can clear these preferences in your browser’s site-data settings. Blocking local storage does not prevent the calculators from working.</p><p>If you choose “Save on this device”, named calculation settings are also stored locally. You can delete individual entries or clear saved calculations in the tool. Copying a settings link includes those inputs in the URL fragment.</p><h2>Hosting</h2><p>The site is hosted on Cloudflare. Like other hosting providers, Cloudflare processes connection information such as IP addresses and request metadata to deliver and protect the website. See ${link('https://www.cloudflare.com/privacypolicy/','Cloudflare’s privacy policy')}.</p><h2>Analytics and advertising</h2><p>This version does not install advertising scripts, third-party analytics, marketing pixels or tracking cookies. If those features are added, this policy must be updated to reflect the actual configuration.</p><h2>Feedback</h2><p>GitHub handles information you choose to submit in a public issue under its own policies. If you email us, your message and email address are used to respond to your request. Avoid posting private information or sending sensitive personal data. Use the ${link('/contact/','contact page')} for the available feedback channel.</p></div>`;
  return `<div class="prose"><p class="lede">Use these tools to calculate and understand everyday time and date questions.</p><h2>Calculation assumptions</h2><p>Results depend on your input, device clock, selected time zone and displayed counting rules. Check those settings before relying on a result. Working days do not include an automatic regional holiday calendar.</p><h2>Alerts</h2><p>Optional sound or browser notifications work only while the page remains open and your browser and device allow them. Closing the page, suspending your device or denying permissions can prevent an alert. These tools do not provide guaranteed alarms.</p><h2>Calendar conventions</h2><p>Calendar dates use the Gregorian calendar. Fixed-unit days mean 24 hours. Calendar months and years depend on the starting date. Month-end dates are clamped to the last valid day when needed.</p><h2>Reporting problems</h2><p>If a result appears incorrect, check the inputs and ${link('/contact/','report a reproducible example')}. The code and test methods are available in the project repository.</p></div>`;
}

function homeContent(){return `<section class="home-hero"><div class="hero-copy"><span class="eyebrow">A CLEARER WAY TO CALCULATE TIME</span><h1>Time and Date<br><em>Calculators</em></h1><p>Measure time between two moments.<br>Count down, convert durations and find dates.</p><div class="hero-actions">${link('/time-duration-calculator/','Calculate time duration','button')}${link('/how-long-until/','Start a countdown','text-link')}${link('/time-duration-converter/','Convert time','text-link')}</div><p id="home-live-count" class="home-live-count">Live countdown calculated on your device</p><div class="hero-proof"><span>${icon('check')} Free to use</span><span>${icon('check')} No account</span><span>${icon('check')} On your device</span></div></div><div class="hero-dial" aria-hidden="true"><div class="dial-ring"><span class="dial-no n12">12</span><span class="dial-no n3">3</span><span class="dial-no n6">6</span><span class="dial-no n9">9</span><div class="dial-hand" id="clock-hand"></div><div class="dial-minute"></div><div class="dial-second"></div><div class="dial-center"></div></div><span class="dial-tag">A moment of clarity.</span></div></section><section class="home-countdown"><div class="section-heading"><div><span class="eyebrow">RIGHT HERE, RIGHT NOW</span><h2>Your next countdown</h2></div>${link('/how-long-until/','All countdowns','arrow-link')}</div>${clockTool({type:'home',hour:15,minute:0},true)}${savedMarkup}</section><section class="tools-directory"><div class="section-heading"><div><span class="eyebrow">FIND YOUR TOOL</span><h2>Everyday questions. Clear answers.</h2></div></div>${groups().map(g=>directory(g,8,'h3')).join('')}<section class="directory-section"><div class="section-heading"><div class="section-icon">${icon('calendar')}</div><div><h3>Holidays & time explained</h3><p>Useful dates and the units behind them.</p></div></div><div class="link-grid">${data.filter(p=>['holiday','definition'].includes(typeOf(p).type)).map(p=>link(p.route,p.h1.replace('?',''),'directory-link')).join('')}</div></section></section>`;}

function relatedLinks(current,p){
  const type=p.type==='converter'?'duration':p.type==='ambiguous'?'clock':p.type;
  const complementary={interval:['/time-calculator/','/date-calculator/','/time-zone-converter/'],event:['/how-long-until/','/time-duration-calculator/','/time-zone-converter/'],dates:['/years-ago-calculator/','/business-days-calculator/','/time-duration-calculator/'],arithmetic:['/time-duration-converter/','/time-duration-calculator/','/date-calculator/'],zones:['/time-duration-calculator/','/countdown-to-date/','/how-long-until/']}[type];
  const candidates=complementary?data.filter(item=>complementary.includes(item.route)):data.filter(item=>item.route!==current.route&&((type==='clock'&&['clock','ambiguous'].includes(typeOf(item).type))||typeOf(item).type===type)&&(type!=='duration'||typeOf(item).unit===p.unit)).sort((a,b)=>{
    const score=item=>{
      const other=typeOf(item);
      if(type==='duration')return (other.unit===p.unit?0:1000000)+Math.abs(other.amount-p.amount);
      if(type==='clock'){
        const distance=Math.abs((other.hour*60+other.minute)-(p.hour*60+p.minute));
        return (other.type===p.type?0:1440)+Math.min(distance,1440-distance);
      }
      if(type==='years')return Math.abs(other.year-p.year);
      if(type==='business')return Math.abs(other.businessMin-p.businessMin);
      return 0;
    };
    return score(a)-score(b)||a.route.localeCompare(b.route);
  });
  const parent={clock:'/how-long-until/',duration:'/time-duration-converter/',business:'/business-days-calculator/',years:'/years-ago-calculator/',holiday:'/holiday-countdown/',definition:'/time-duration-converter/'}[type];
  return `<section class="related"><div class="section-heading"><h2>Related tools</h2>${parent?link(parent,'Open all','arrow-link'):''}</div><div class="link-grid">${candidates.slice(0,8).map(item=>link(item.route,item.h1.replace('?',''),'directory-link')).join('')}${parent&&parent!==current.route?link(parent,'Use the general calculator','directory-link'):''}</div></section>`;
}

const searchAliases={interval:'duration calculator time difference elapsed time 9 to 5 hours between times',event:'date countdown birthday anniversary exam meeting',dates:'date difference days between dates date addition subtraction',arithmetic:'time addition subtraction hours minutes seconds',zones:'time zone converter timezone local time UTC EST PST'};
const searchIndex=data.filter(p=>typeOf(p).type!=='legal').map(p=>({route:p.route,label:p.h1,terms:[searchAliases[typeOf(p).type]??'',...keywords.filter(k=>k.route===p.route).map(k=>k.keyword)].join(' ')}));
for(const item of data){
  const p=typeOf(item),isHome=p.type==='home',breadcrumbs=breadcrumbItems(item,p);
  let main='';
  if(isHome)main=homeContent();
  else{
    const category=['clock','ambiguous'].includes(p.type)?'COUNTDOWN TO A TIME':p.type==='holiday'?'HOLIDAY COUNTDOWN':p.type==='duration'||p.type==='converter'?'TIME DURATION CONVERTER':p.type==='business'?'BUSINESS DAYS & DATES':p.type==='years'?'DATE & YEAR CALCULATOR':p.type==='definition'?'TIME, EXPLAINED':esc(config.name.toUpperCase());
    main=`<nav class="breadcrumb" aria-label="Breadcrumb">${breadcrumbs.map((b,i)=>`${i?'<span aria-hidden="true">/</span>':''}${i===breadcrumbs.length-1?`<span aria-current="page">${esc(b.name)}</span>`:link(b.route,b.name)}`).join('')}</nav><section class="page-intro"><span class="eyebrow">${category}</span><h1>${esc(item.h1)}</h1></section>`;
    if(item.tool)main+=extraTool(p,{label,select,dateInput,copyButton,resultSummary,status});
    else if(['clock','ambiguous','holiday'].includes(p.type))main+=clockTool(p);
    else if(['duration','converter'].includes(p.type))main+=durationTool(p);
    else if(p.type==='business')main+=businessTool(p);
    else if(p.type==='years')main+=yearsTool(p);
    else if(p.type==='definition')main+=definitionTool(p);
    else if(p.type==='holiday-hub')main+=`<p class="lede">Live countdowns to clearly defined holiday dates, in your selected time zone.</p><div class="link-grid">${data.filter(x=>typeOf(x).type==='holiday').map(x=>link(x.route,x.h1,'directory-link')).join('')}</div>`;
    else main+=legalContent(item.route);
    if(!['legal','holiday-hub','definition'].includes(p.type))main+=savedMarkup;
    main+=explanation(p,item.route);
    main+=calculationSources(p);
    if(!['legal','holiday-hub','clock','ambiguous','holiday'].includes(p.type))main+='<noscript><p class="notice">Interactive calculations need JavaScript. The fixed answers, calculation rules and tool links remain available.</p></noscript>';
    if(item.route==='/how-long-until/')main+=directory(groups()[0]);
    else if(item.route==='/time-duration-converter/')main+=directory(groups()[1]);
    else if(item.route==='/business-days-calculator/')main+=directory(groups()[2]);
    else if(item.route==='/years-ago-calculator/')main+=directory(groups()[3]);
    if(!['legal','holiday-hub'].includes(p.type))main+=relatedLinks(item,p);
  }
  if(isHome||item.tool||['/how-long-until/','/time-duration-converter/','/business-days-calculator/','/years-ago-calculator/'].includes(item.route))main+=toolLinks();
  const pageTitle=item.title??item.h1;
  const title=pageTitle.includes(config.name)?pageTitle:pageTitle+' | '+config.name;
  const description=item.route==='/years-ago-calculator/'?'Calculate years, months and days since a year or exact date. Choose a reference date and compare calendar-year or month endpoints.':item.description??(p.type==='duration'?`${durationAnswer(p)} See exact conversions, the calculation and a ready-to-use time converter.`:p.type==='clock'||p.type==='ambiguous'?`${item.h1} Get a live countdown in your time zone, with an explicit target date, AM/PM options and hours, minutes and seconds.`:p.type==='years'?`Calculate how long ago ${p.year} was using a visible reference date. Compare the start and end of the year or choose an exact date.`:`${item.h1}. ${config.description}`);
  const schema={'@context':'https://schema.org','@graph':[
    {'@type':'WebSite','@id':siteURL+'/#website',name:config.name,url:siteURL+'/',inLanguage:'en'},
    {'@type':'WebPage','@id':siteURL+item.route+'#webpage',name:item.h1,url:siteURL+item.route,description,inLanguage:'en',isPartOf:{'@id':siteURL+'/#website'},...(breadcrumbs.length?{breadcrumb:{'@id':siteURL+item.route+'#breadcrumb'}}:{})},
    ...(breadcrumbs.length?[{'@type':'BreadcrumbList','@id':siteURL+item.route+'#breadcrumb',itemListElement:breadcrumbs.map((b,i)=>({'@type':'ListItem',position:i+1,name:b.name,item:siteURL+b.route}))}]:[])
  ]};
  const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="${siteURL}${item.route}"><meta name="robots" content="${publicBuild?'index,follow':'noindex,nofollow'}"><meta property="og:type" content="website"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:url" content="${siteURL}${item.route}"><meta name="theme-color" content="#f6f7f3"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/styles.css"><script type="application/ld+json">${json(schema)}</script></head><body>${header(['ambiguous','home','holiday'].includes(p.type)?'clock':p.type==='converter'?'duration':p.type)}<main id="main" class="container">${main}</main>${footer()}<dialog id="search-dialog" aria-labelledby="search-title"><div class="search-heading"><h2 id="search-title">Find a time tool</h2><button type="button" id="close-search" class="icon-button" aria-label="Close search">${icon('close')}</button></div><label for="tool-search">Search by time, duration or task</label><input id="tool-search" type="search" placeholder="Try 3 PM, 72 hours, business days…"><p id="search-count" role="status"></p><ul id="search-results"></ul></dialog><script id="page-config" type="application/json">${json(p)}</script><script id="search-index" type="application/json">${json(searchIndex)}</script><script type="module" src="/assets/app.js"></script></body></html>`;
  const target=path.join(dist,item.route,'index.html');await fs.mkdir(path.dirname(target),{recursive:true});await fs.writeFile(target,html.replace('/assets/styles.css"',`/assets/styles.css?v=${assetVersion}"`).replace('/assets/app.js"',`/assets/app.js?v=${assetVersion}"`));
}
await fs.copyFile(path.join(root,'src/styles.css'),path.join(dist,'assets/styles.css'));
await fs.writeFile(path.join(dist,'favicon.svg'),'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="18" fill="#203b35"/><circle cx="32" cy="32" r="20" fill="none" stroke="#d6e8ad" stroke-width="3"/><path d="M32 19v14l10 6" fill="none" stroke="#d6e8ad" stroke-width="3" stroke-linecap="round"/></svg>');
await fs.writeFile(path.join(dist,'robots.txt'),publicBuild?`User-agent: *\nAllow: /\nSitemap: ${siteURL}/sitemap.xml\n`:'User-agent: *\nDisallow: /\n');
await fs.writeFile(path.join(dist,'sitemap.xml'),`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${data.map(p=>`<url><loc>${siteURL}${p.route}</loc></url>`).join('')}</urlset>`);
await fs.writeFile(path.join(dist,'404.html'),`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Page not found | ${esc(config.name)}</title><meta name="robots" content="noindex"><link rel="stylesheet" href="/assets/styles.css"></head><body>${header('')}<main class="container error-page"><span class="eyebrow">404 · PAGE NOT FOUND</span><h1>Let’s get you back<br>to the right time.</h1><p>This address doesn’t match one of our tools.</p>${link('/','Browse all calculators','button')}</main>${footer()}</body></html>`);
await fs.writeFile(path.join(dist,'_headers'),`/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n  Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; font-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'\n/assets/*\n  Cache-Control: public, max-age=3600\n`);
await fs.writeFile(path.join(dist,'_redirects'),'/how-long-till/3-pm/ /how-long-until/3-pm/ 301\n/how-long-until/3pm/ /how-long-until/3-pm/ 301\n');
await fs.mkdir(path.join(root,'docs'),{recursive:true});
await fs.writeFile(path.join(root,'docs/keyword-coverage.md'),`# Keyword coverage\n\n83 original keywords and 17 screenshot variants map to 64 landing pages. The full site has ${data.length} pages. This documents implementation coverage, not ranking guarantees.\n\n| Keyword | Primary page | Source |\n|---|---|---|\n${keywords.map(k=>`| ${k.keyword} | ${k.route} | ${k.source} |`).join('\n')}\n`);
console.log(`Built ${data.length} HTML pages; ${keywords.filter(k=>k.source==='original').length} original keywords mapped. Origin: ${siteURL}; indexing: ${publicBuild}.`);
